class Twin1 extends Parent1 {
    Twin2 twin;                        // pair-internal access
    void click()  { twin.toggleSuspended(); }
}
class Twin2 extends Parent2 {
    Twin1 twin;
    void run()    { while (alive) { twin.draw(); twin.move(); } }
}
Twin1 create(...) {                    // factory: the pair is created, never one end
    a = new Twin1(...); b = new Twin2(...);
    a.twin = b; b.twin = a; return a;  // link before publishing
}
